import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.DJS_B2uc.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Breeze Server","text":"Breeze for ASP.NET Core","tagline":"Describe your model to the client, run the queries it composes, and save its whole change-set in one transaction - on .NET 8, 9 and 10, with Entity Framework Core or NHibernate.","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Upgrading from 7.x","link":"https://github.com/Breeze/breeze-server-v3/blob/master/UPGRADE.md"},{"theme":"alt","text":"API reference","link":"/api/","target":"_self"}]},"features":[{"title":"Your model, described once","details":"The client learns entity types, keys, relationships and validation from the Entity Framework Core or NHibernate mapping you already have.","link":"/guide/metadata"},{"title":"Queries the client composed","details":"One endpoint per entity set. Filter, sort, page and expand reach the database as SQL - within the limits you set.","link":"/guide/querying"},{"title":"Whole change-sets, one transaction","details":"Added, modified and deleted entities of every type are saved together, with interceptors for the rules that are yours.","link":"/guide/saving"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1790831663000}'),n={name:"index.md"};function i(s,e,d,h,l,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<p>This site documents the .NET server-side packages of <strong>Breeze</strong>, a library from <a href="https://www.ideablade.com/" target="_blank" rel="noreferrer">IdeaBlade</a> that helps you manage data in rich client applications. It covers version 8.0.0, which targets .NET 8, 9 and 10 on ASP.NET Core.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Looking for the client?</strong> The Breeze client documentation - guides and the TypeScript API reference - is at <strong><a href="https://breeze.github.io/breeze-client-v3/" target="_blank" rel="noreferrer">breeze.github.io/breeze-client-v3</a></strong>. Start with <a href="https://breeze.github.io/breeze-client-v3/server/dotnet" target="_blank" rel="noreferrer">Using a Breeze .NET server</a> for how a client talks to the server documented here.</p></div><h2 id="what-the-breeze-server-does" tabindex="-1">What the Breeze server does <a class="header-anchor" href="#what-the-breeze-server-does" aria-label="Permalink to &quot;What the Breeze server does&quot;">​</a></h2><p>A Breeze client holds a cache of entities. It composes queries against them, tracks what the user changes, and saves everything in one go. None of that works against an ordinary REST API, because an ordinary REST API answers only the questions its author thought of in advance, and accepts only the shapes its author declared.</p><p>The server packages close that gap. They add three things to an ASP.NET Core application:</p><h3 id="_1-they-describe-your-model-to-the-client" tabindex="-1">1. They describe your model to the client <a class="header-anchor" href="#_1-they-describe-your-model-to-the-client" aria-label="Permalink to &quot;1. They describe your model to the client&quot;">​</a></h3><p><code>PersistenceManager.Metadata()</code> reads your Entity Framework Core or NHibernate mapping and returns it as JSON: entity types, their properties and data types, keys, relationships, which properties are required, how long a string may be, and which column is the concurrency token.</p><p>The client builds its own model from that document. It is what lets the client create a valid entity, follow <code>customer.orders[0].orderDetails</code>, know that a change is a change, and reject a too-long <code>CompanyName</code> before a request is ever sent. You write no schema twice: the mapping you already have is the description.</p><h3 id="_2-they-run-queries-the-client-composed" tabindex="-1">2. They run queries the client composed <a class="header-anchor" href="#_2-they-run-queries-the-client-composed" aria-label="Permalink to &quot;2. They run queries the client composed&quot;">​</a></h3><p>The client builds a query — filter, sort, page, project, include related types — and sends it as JSON in the URL. <code>[BreezeQueryFilter]</code> applies it to the <code>IQueryable</code> your action returned, before it is serialized. So it reaches the database as SQL, with the filter in the <code>WHERE</code> clause rather than in memory afterwards.</p><p>The practical effect is on how many endpoints you write:</p><table tabindex="0"><thead><tr><th></th><th>without Breeze</th><th>with Breeze</th></tr></thead><tbody><tr><td>query endpoints</td><td>one per question - <code>GetCustomers</code>, <code>GetCustomersByCity</code>, <code>GetCustomersByCityPaged</code> …</td><td>one per entity set, returning <code>IQueryable&lt;T&gt;</code></td></tr><tr><td>a new filter the UI needs</td><td>a new endpoint, deployed</td><td>nothing; the client already can</td></tr></tbody></table><p>That is also why <a href="./guide/querying">Querying</a> spends most of its length on <code>MaxDepth</code> and <code>MaxTake</code>. A query that arrives from a browser is user input, and the point of the feature is that you did not enumerate what it may ask for.</p><h3 id="_3-they-apply-a-whole-change-set-at-once" tabindex="-1">3. They apply a whole change-set at once <a class="header-anchor" href="#_3-they-apply-a-whole-change-set-at-once" aria-label="Permalink to &quot;3. They apply a whole change-set at once&quot;">​</a></h3><p><code>SaveChanges</code> receives one document containing every pending change — added, modified and deleted entities, of as many types as the user touched, each carrying its state and its original values. The <code>PersistenceManager</code> turns that back into real entities attached in the right states, saves them in one transaction, and reports back the keys the database generated in place of the temporary ones the client invented.</p><p>So a screen that adds an order, edits two of its lines and deletes a third is one request that succeeds or fails as a unit — not four, in an order you had to choose, with partial failure to unpick.</p><h3 id="and-they-translate-errors" tabindex="-1">And they translate errors <a class="header-anchor" href="#and-they-translate-errors" aria-label="Permalink to &quot;And they translate errors&quot;">​</a></h3><p>A failed save comes back as an <a href="https://www.rfc-editor.org/rfc/rfc9457" target="_blank" rel="noreferrer">RFC 9457</a> problem details document carrying <em>which entity</em> failed and <em>why</em>, so the client can attach the message to the offending record rather than showing one dialog for the batch. Optimistic concurrency conflicts arrive with a stable problem type, identical whether Entity Framework Core or NHibernate raised them. See <a href="./guide/error-handling">Error handling</a>.</p><h3 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h3><p>It is a library, not a framework, and it is deliberately small:</p><ul><li><strong>It does not replace your <code>DbContext</code> or your mappings.</strong> It reads them. Your entities, configuration and migrations are unchanged.</li><li><strong>Your controllers are ordinary controllers.</strong> Nothing is scaffolded or generated; see <a href="./guide/getting-started">Getting started</a> for the whole of one.</li><li><strong>It does nothing about authentication or authorization.</strong> That is ASP.NET Core&#39;s job as usual. What is yours to write is <em>what a given user may query and change</em> - the save hooks in <a href="./guide/saving">Saving</a> are where that belongs, because a save bundle names its own entity types and original values and is therefore untrusted input.</li><li><strong>It is not OData.</strong> The query format is Breeze&#39;s own, and the client speaks it out of the box.</li></ul><hr><p>This site has two halves: a hand-written <strong><a href="./guide/getting-started">Guide</a></strong>, and an <strong><a href="/breeze-server-v3/api/Breeze.Persistence.html" target="_self">API reference</a></strong> generated from the XML doc comments in <a href="https://github.com/Breeze/breeze-server-v3" target="_blank" rel="noreferrer">breeze-server-v3</a>. The <em>API</em> link above reaches the whole of it; the table below starts at each package.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><a href="./guide/getting-started">Getting started</a></td><td>from an empty project to a working Breeze endpoint</td></tr><tr><td><a href="./guide/persistence-manager">The PersistenceManager</a></td><td>the server side of Breeze, and its lifetime</td></tr><tr><td><a href="./guide/querying">Querying</a></td><td>the query filter, and limiting what clients may ask for</td></tr><tr><td><a href="./guide/saving">Saving</a></td><td>interceptors, transactions and key mappings</td></tr><tr><td><a href="./guide/security">Security</a></td><td>the query and the change-set both come from the browser</td></tr><tr><td><a href="./guide/metadata">Metadata</a></td><td>what the client is told about your model</td></tr><tr><td><a href="./guide/error-handling">Error handling</a></td><td>returning errors a client can act on</td></tr></tbody></table><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Namespace</th><th>Purpose</th></tr></thead><tbody><tr><td>Breeze.AspNetCore.NetCore</td><td><a href="/breeze-server-v3/api/Breeze.AspNetCore.html" target="_self">Breeze.AspNetCore</a></td><td>ASP.NET Core integration - <code>[BreezeQueryFilter]</code> and friends</td></tr><tr><td>Breeze.Persistence.EFCore</td><td><a href="/breeze-server-v3/api/Breeze.Persistence.EFCore.html" target="_self">Breeze.Persistence.EFCore</a></td><td>Entity Framework Core support - start at <a href="/breeze-server-v3/api/Breeze.Persistence.EFCore.EFPersistenceManager-1.html" target="_self"><code>EFPersistenceManager&lt;T&gt;</code></a></td></tr><tr><td>Breeze.Persistence.NH</td><td><a href="/breeze-server-v3/api/Breeze.Persistence.NH.html" target="_self">Breeze.Persistence.NH</a></td><td>NHibernate support</td></tr><tr><td>Breeze.Persistence</td><td><a href="/breeze-server-v3/api/Breeze.Persistence.html" target="_self">Breeze.Persistence</a></td><td>Shared persistence layer - <a href="/breeze-server-v3/api/Breeze.Persistence.PersistenceManager.html" target="_self"><code>PersistenceManager</code></a></td></tr><tr><td>Breeze.Core</td><td><a href="/breeze-server-v3/api/Breeze.Core.html" target="_self">Breeze.Core</a></td><td>Query parsing and JSON serialization</td></tr></tbody></table><p>A typical EF Core application installs the first two; the last two are pulled in automatically.</p><p>The reference is built from the <code>net10.0</code> target. The public API is the same on <code>net8.0</code> and <code>net9.0</code>, except that each target references the matching major version of Entity Framework Core.</p><h2 id="more-documentation" tabindex="-1">More documentation <a class="header-anchor" href="#more-documentation" aria-label="Permalink to &quot;More documentation&quot;">​</a></h2><ul><li><strong>Breeze client documentation</strong> - guides and the TypeScript API reference - is at <a href="https://breeze.github.io/breeze-client-v3/" target="_blank" rel="noreferrer">breeze.github.io/breeze-client-v3</a>, built from <a href="https://github.com/Breeze/breeze-client-v3" target="_blank" rel="noreferrer">breeze-client-v3</a>.</li><li><strong>Upgrading from 7.x</strong> - <a href="https://github.com/Breeze/breeze-server-v3/blob/master/UPGRADE.md" target="_blank" rel="noreferrer">UPGRADE.md</a> in breeze-server-v3.</li><li><strong>Earlier versions</strong> - the 7.x and ASP.NET 4.x documentation is still at <a href="https://breeze.github.io/doc-net/?v2" target="_blank" rel="noreferrer">breeze.github.io/doc-net</a>.</li></ul>',31)])])}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
